(function (global) {
    const INTERACTIVE = 'a[href], button, input, select, textarea, [tabindex]:not([tabindex="-1"])';

    const PP_TooltipsLibrary = {
        counter: 0,

        init() {
            this.applyTooltips(document);
            this.bindGlobalClick();
            this.bindDismiss();
        },

        nextTooltipId() {
            this.counter += 1;
            return 'ppseries-tooltip-' + this.counter;
        },

        toggle(tooltip) {
            tooltip.classList.remove('is-dismissed');
            const isActive = tooltip.classList.toggle('is-active');
            if (tooltip.classList.contains('click')) {
                tooltip.setAttribute('aria-expanded', isActive ? 'true' : 'false');
            }
        },

        applyTooltips(context = document) {
            const tooltips = context.querySelectorAll('[data-toggle="tooltip"].pp-tooltips-library');

            tooltips.forEach(tooltip => {
                if (tooltip.dataset.tooltipProcessed === 'true') {
                    return;
                }

                tooltip.dataset.tooltipProcessed = 'true';
                const tooltipBox = tooltip.querySelector('.tooltip-text');

                if (!tooltipBox) {
                    return;
                }

                tooltip.tabIndex = 0;

                if (!tooltipBox.id) {
                    tooltipBox.id = this.nextTooltipId();
                }

                tooltipBox.setAttribute('role', 'tooltip');
                tooltip.setAttribute('aria-describedby', tooltipBox.id);

                // A button must not contain other interactive content.
                const hasInteractiveChild = Array.prototype.some.call(
                    tooltip.querySelectorAll(INTERACTIVE),
                    el => !tooltipBox.contains(el)
                );
                if (!hasInteractiveChild) {
                    tooltip.setAttribute('role', 'button');
                }

                if (tooltip.classList.contains('click')) {
                    tooltip.setAttribute('aria-expanded', 'false');
                    tooltip.addEventListener('click', event => {
                        event.preventDefault();
                        event.stopPropagation();
                        this.toggle(tooltip);
                    });
                }

                tooltip.addEventListener('keydown', event => {
                    if (event.key !== 'Enter' && event.key !== ' ') {
                        return;
                    }
                    if (event.target !== tooltip) {
                        return;
                    }

                    event.preventDefault();
                    event.stopPropagation();
                    this.toggle(tooltip);
                });

                // Re-allow the tooltip after an Escape dismissal once the pointer/focus leaves.
                tooltip.addEventListener('mouseleave', () => {
                    if (!tooltip.contains(document.activeElement)) {
                        tooltip.classList.remove('is-dismissed');
                    }
                });
                tooltip.addEventListener('focusout', event => {
                    if (!tooltip.contains(event.relatedTarget)) {
                        tooltip.classList.remove('is-dismissed', 'is-active');
                        if (tooltip.classList.contains('click')) {
                            tooltip.setAttribute('aria-expanded', 'false');
                        }
                    }
                });

                const arrow = tooltipBox.querySelector('i');
                if (arrow) {
                    arrow.setAttribute('aria-hidden', 'true');
                } else {
                    const newArrow = document.createElement('i');
                    newArrow.setAttribute('aria-hidden', 'true');
                    tooltipBox.appendChild(newArrow);
                }
            });

            // PRO lock tooltips: Escape support and pointer reset.
            context.querySelectorAll('.ppseries-pro-lock').forEach(lock => {
                if (lock.dataset.tooltipProcessed === 'true') {
                    return;
                }
                lock.dataset.tooltipProcessed = 'true';
                lock.addEventListener('mouseleave', () => {
                    if (!lock.contains(document.activeElement)) {
                        lock.classList.remove('is-dismissed');
                    }
                });
                lock.addEventListener('focusout', event => {
                    if (!lock.contains(event.relatedTarget)) {
                        lock.classList.remove('is-dismissed');
                    }
                });
            });
        },

        bindGlobalClick() {
            document.addEventListener('click', event => {
                const tooltip = event.target.closest('[data-toggle="tooltip"].pp-tooltips-library.click');

                if (!tooltip) {
                    return;
                }

                event.preventDefault();
                event.stopPropagation();
                this.toggle(tooltip);
            });
        },

        /**
         * Escape dismisses any visible tooltip (hover, focus or toggled) without moving focus.
         */
        bindDismiss() {
            document.addEventListener('keydown', event => {
                if (event.key !== 'Escape' && event.key !== 'Esc') {
                    return;
                }

                let dismissed = false;
                document.querySelectorAll('[data-toggle="tooltip"].pp-tooltips-library, .ppseries-pro-lock').forEach(tooltip => {
                    const visible = tooltip.classList.contains('is-active')
                        || tooltip.matches(':hover')
                        || tooltip.matches(':focus-within');

                    if (!visible || tooltip.classList.contains('is-dismissed')) {
                        return;
                    }

                    tooltip.classList.remove('is-active');
                    tooltip.classList.add('is-dismissed');
                    if (tooltip.classList.contains('click')) {
                        tooltip.setAttribute('aria-expanded', 'false');
                    }
                    dismissed = true;
                });

                // Don't let the same Escape close a surrounding dialog.
                if (dismissed) {
                    event.stopPropagation();
                }
            });
        },

        refresh(context = document) {
            this.applyTooltips(context);
        }
    };

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => PP_TooltipsLibrary.init());
    } else {
        PP_TooltipsLibrary.init();
    }
    global.PP_TooltipsLibrary = PP_TooltipsLibrary;
}(window));
